// Command asn1gen generates Go types with github.com/free5gc/aper struct tags from the
// NGAP ASN.1 modules of 3GPP TS 38.413 clause 9.4 (NGAP-PDU-Descriptions, NGAP-PDU-Contents,
// NGAP-IEs, NGAP-CommonDataTypes, NGAP-Constants, NGAP-Containers). The output follows
// the shapes and names of free5gc/ngap ngapType.
//
// Usage:
//
//	asn1gen -in specs/asn1/ngap/r19 -out shared/ngap/ngapType -pkg ngapType \
//	        -header "Code generated by tools/asn1gen from TS 38.413 V19.4.0. DO NOT EDIT."
//
// Flags:
//
//	-in DIR       directory holding the *.asn modules (fetched with scripts/extract-asn1.sh;
//	              git-ignored, the 3GPP text is never committed)
//	-out DIR      output directory (created); previously generated *.go files in it, i.e.
//	              files whose first line starts with "// Code generated by tools/asn1gen",
//	              are removed first so a re-run is reproducible
//	-pkg NAME     Go package name (default ngapType)
//	-header TEXT  first comment line of every file; must start with "Code generated"
//	              (default "Code generated by tools/asn1gen. DO NOT EDIT.")
//	-aper PATH    import path of the aper library (default github.com/free5gc/aper)
//
// Exit status is 0 on success, 1 on a parse or generation error, 2 on a usage error.
package main

import (
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/francurieses/claudia-5gc/tools/asn1gen/internal/asn1"
	"github.com/francurieses/claudia-5gc/tools/asn1gen/internal/gogen"
)

// generatedMarker identifies files this tool owns (and may delete on re-generation).
const generatedMarker = "// Code generated by tools/asn1gen"

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

func run(args []string, stdout, stderr io.Writer) int {
	fs := flag.NewFlagSet("asn1gen", flag.ContinueOnError)
	fs.SetOutput(stderr)
	in := fs.String("in", "", "directory with the *.asn modules")
	out := fs.String("out", "", "output directory")
	pkg := fs.String("pkg", "ngapType", "Go package name")
	header := fs.String("header", "Code generated by tools/asn1gen. DO NOT EDIT.", "first comment line of each file")
	aper := fs.String("aper", "github.com/free5gc/aper", "aper import path")
	if err := fs.Parse(args); err != nil {
		return 2
	}
	if *in == "" || *out == "" || !strings.HasPrefix(*header, "Code generated by tools/asn1gen") {
		fmt.Fprintln(stderr, "asn1gen: -in and -out are required; -header must start with \"Code generated by tools/asn1gen\"")
		fs.Usage()
		return 2
	}
	files, err := Generate(*in, gogen.Config{Package: *pkg, Header: *header, AperImport: *aper})
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 1
	}
	if err := write(*out, files); err != nil {
		fmt.Fprintln(stderr, err)
		return 1
	}
	fmt.Fprintf(stdout, "asn1gen: wrote %d files to %s\n", len(files), *out)
	return 0
}

// Generate parses every *.asn file of dir (in file name order) and generates the Go sources.
func Generate(dir string, cfg gogen.Config) (map[string][]byte, error) {
	paths, err := filepath.Glob(filepath.Join(dir, "*.asn"))
	if err != nil {
		return nil, fmt.Errorf("asn1gen: list %s: %w", dir, err)
	}
	if len(paths) == 0 {
		return nil, fmt.Errorf("asn1gen: no *.asn files in %s", dir)
	}
	sort.Strings(paths)
	var mods []*asn1.Module
	for _, p := range paths {
		b, err := os.ReadFile(p)
		if err != nil {
			return nil, fmt.Errorf("asn1gen: read %s: %w", p, err)
		}
		m, err := asn1.ParseModule(filepath.Base(p), string(b))
		if err != nil {
			return nil, err
		}
		mods = append(mods, m)
	}
	return gogen.Generate(mods, cfg)
}

func write(dir string, files map[string][]byte) error {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return fmt.Errorf("asn1gen: create %s: %w", dir, err)
	}
	old, err := filepath.Glob(filepath.Join(dir, "*.go"))
	if err != nil {
		return fmt.Errorf("asn1gen: list %s: %w", dir, err)
	}
	for _, p := range old {
		b, err := os.ReadFile(p)
		if err != nil {
			return fmt.Errorf("asn1gen: read %s: %w", p, err)
		}
		if first, _, _ := strings.Cut(string(b), "\n"); strings.HasPrefix(first, generatedMarker) {
			if err := os.Remove(p); err != nil {
				return fmt.Errorf("asn1gen: remove stale %s: %w", p, err)
			}
		}
	}
	for name, content := range files {
		if err := os.WriteFile(filepath.Join(dir, name), content, 0o644); err != nil {
			return fmt.Errorf("asn1gen: write %s: %w", name, err)
		}
	}
	return nil
}
